widget.draw:
function draw(ctx, state, t) {
function fmt(v) { return Math.round(v * 100) / 100; }


var w = state.w;
var h = state.h;
var d = state.d;
var r = state.r;
var lora = 2 * d * r;
var full = d * d;
var reg = d / 2;
ctx.clearRect(0, 0, w, h);
ctx.fillStyle = "#f6f3ec";
ctx.fillRect(0, 0, w, h);
var bw = r * 6;
var bh = 40 + d * 3;
var aw = 40 + d * 3;
var ah = r * 6;
var ww = 40 + d * 3;
var wh = 40 + d * 3;
ctx.fillStyle = "#1f4b99";
ctx.fillRect(40, 70, bw, bh);
ctx.fillStyle = "#c4512c";
ctx.fillRect(150, 70, aw, ah);
ctx.fillStyle = "#2a7a3b";
ctx.fillRect(380, 70, ww, wh);
ctx.strokeStyle = "#111111";
ctx.lineWidth = 1;
ctx.strokeRect(40, 70, bw, bh);
ctx.strokeRect(150, 70, aw, ah);
ctx.strokeRect(380, 70, ww, wh);
ctx.fillStyle = "#111111";
ctx.font = "12px sans-serif";
ctx.textAlign = "left";
ctx.fillText("not to scale", 40, 28);
ctx.fillText("B bloque", 40, 58);
ctx.fillText("A bloque", 150, 58);
ctx.fillText("W completa", 380, 58);
ctx.fillText("d = " + fmt(d), 40, 250);
ctx.fillText("r = " + fmt(r), 130, 250);
var yL = 250 - r * 6;
ctx.fillText("lora_params = " + fmt(lora), 220, yL);
ctx.fillText("full_params = " + fmt(full), 380, 250);
var x0 = 40;
var x1 = 600;
var yR = 320;
var regX = x0 + reg / 16 * (x1 - x0);
var rX = x0 + r / 16 * (x1 - x0);
ctx.strokeStyle = "#111111";
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(x0, yR);
ctx.lineTo(x1, yR);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(regX, yR - 10);
ctx.lineTo(regX, yR + 10);
ctx.stroke();
ctx.fillStyle = "#1f4b99";
ctx.fillRect(rX - 3, yR - 3, 6, 6);
ctx.fillStyle = "#111111";
ctx.fillText("r mitad de d = " + fmt(reg), regX + 8, yR + 4);
ctx.fillText("r actual", rX - 20, yR + 26);
}
